// Icon system guardrails: every icon on the site comes from public/icons.svg
// (generated by scripts/build-icons.mjs from the UI_ICON_NAMES catalog in
// public/public.js), nothing draws its own glyph paths any more, and the
// sprite on disk matches the catalog.

import assert from "node:assert/strict";
import { readFile, readdir } from "node:fs/promises";

const root = new URL("../", import.meta.url);
const publicRoot = new URL("public/", root);
const read = (name) => readFile(new URL(name, publicRoot), "utf8");

const sprite = await read("icons.svg");
const spriteIds = new Set([...sprite.matchAll(/<symbol id="([a-z0-9-]+)"/g)].map((m) => m[1]));
const publicJs = await read("public.js");
const catalog = new Set([...publicJs.match(/const UI_ICON_NAMES = new Set\(\[([\s\S]*?)\]\);/)[1].matchAll(/"([a-z0-9-]+)"/g)].map((m) => m[1]));

assert.deepEqual([...spriteIds].sort(), [...catalog].sort(), "public/icons.svg is stale - run `npm run icons`");

const files = (await readdir(publicRoot)).filter((name) => name.endsWith(".html") || name.endsWith(".js"));
const used = new Map(); // name -> first file
const offenders = [];
for (const name of files) {
  const source = await read(name);
  for (const m of source.matchAll(/icons\.svg#([a-z0-9-]+)/g)) used.set(m[1], name);
  for (const m of source.matchAll(/(?:uiIcon|icon|linkActionButton|shareActionButton)\(\s*"([a-z0-9-]+)"/g)) used.set(m[1], name);
  for (const m of source.matchAll(/return "([a-z0-9-]+)";/g)) if (name === "admin.js" && catalog.has(m[1])) used.set(m[1], name);
  // Hand-drawn glyphs are what let the icon set drift; only data
  // visualisations (rings, sparklines, charts) may still carry <path>.
  const svgs = [...source.matchAll(/<svg\b[^>]*>[\s\S]*?<\/svg>/g)].map((m) => m[0]);
  for (const svg of svgs) {
    if (svg.includes("icons.svg#") || /class="(chart-svg|[^"]*live-ring)|preserveAspectRatio|viewBox="0 0 (44|62) /.test(svg)) continue;
    if (/<(path|polygon|polyline|rect|circle|line)\b/.test(svg)) offenders.push(`${name}: ${svg.slice(0, 80)}…`);
  }
}
assert.equal(offenders.length, 0, `inline glyphs bypass the icon catalog:\n${offenders.join("\n")}`);

const unknown = [...used].filter(([n]) => !catalog.has(n));
assert.equal(unknown.length, 0, `icons referenced but not in UI_ICON_NAMES: ${unknown.map(([n, f]) => `${n} (${f})`).join(", ")}`);

const adminSource = await read("admin.js");
const css = await read("style.css");
assert.match(adminSource, /class="stat-label"/, "Overview stat cards use an explicit label hook");
assert.doesNotMatch(adminSource, /querySelector\(["']div > span["']\)/, "stat labels never target the icon span structurally");
assert.match(publicJs, /throw new Error\(`Unknown icon:/, "unknown dynamic icons fail loudly instead of rendering blank");
assert.match(css, /\.stat-card\.v3 \.stat-ico\s*\{[\s\S]*?margin-bottom:\s*0;/, "stat icon tiles reset legacy span spacing");
assert.match(css, /\.stat-card\.v3 \.stat-label\s*\{/, "stat label typography is scoped to the explicit label hook");
assert.doesNotMatch(css, /\.ico-fill\b|\.duo\b/, "legacy fill/duotone icon classes are gone");

console.log(`icon audit passed (${catalog.size} catalog icons, ${used.size} referenced)`);
